"""Pin final native receipts and calculate fair recovery/supply endpoints."""
import argparse, gzip, hashlib, json, re
from pathlib import Path

p=argparse.ArgumentParser();p.add_argument('--input-dir',required=True);a=p.parse_args()
root=Path(__file__).resolve().parents[1];src=Path(a.input_dir);folder=root/'docs/data/balance_v01627/ordinary_final';rawdir=folder/'raw';rawdir.mkdir(parents=True,exist_ok=True)
