def load(name):return json.loads((src/(name+'.json')).read_text())
def cash(q):return sum(q.get(k,0) for k in ['purchasedMora','processCraftMora','foodCraftMora'])
def choose(rows,seed,stage):return next(x for x in rows if x['seed']==seed and x['stage']==stage and x.get('route','ROUTE_TRAVELER')=='ROUTE_TRAVELER' and x.get('name','heal5')=='heal5')
